/** Validate all reachable records once. Cycles do not skip a node's validation. */
export function assertUsable(root, target) {
  const registry = loadRegistry(root);
  const seen = new Set();
  const pending = [target, ...GOVERNANCE];
  while (pending.length) {
    const relative = pending.pop();
    if (seen.has(relative)) continue;
    const rec = validateRecord(root, registry, relative);
    seen.add(relative);
    pending.push(...rec.dependencies);
  }
  return {status: 'VALIDATED_RECORDS', context_id: registry.context_id, checked: [...seen].sort()};

export function loadRegistry(root) {
  const value = strictRegistryJSON(fs.readFileSync(safeFile(root, '.opencode/audit/registry.json'), 'utf8'));
  if (!object(value) || value.schema_version !== 1 || !object(value.records)
      || !nonempty(value.context_id) || value.context_id === 'UNCONFIGURED') {
    throw new Error('Audit registry missing, malformed, or context UNCONFIGURED; perform a read-only bootstrap audit');
  }
  return value;

} else if (action === 'inventory' && targets.length === 0) {
  const files = [];
  function visit(dir) {
    for (const entry of fs.readdirSync(path.join(root, dir), {withFileTypes: true})) {
      const rel = path.posix.join(dir, entry.name);
      if (entry.isSymbolicLink()) throw new Error(`Refusing symlink: ${rel}`);
      if (entry.isDirectory()) visit(rel);
      else if (entry.isFile()) files.push({path: rel, sha256: fingerprint(root, rel)});
    }
  }
  for (const dir of ['.opencode/skills', '.opencode/agents', '.opencode/rules', '.opencode/hooks']) visit(dir);
  console.log(JSON.stringify({status: 'INVENTORY_ONLY_NOT_SEMANTIC_APPROVAL', files}, null, 2));
